task:
Security review of a pending change. The diff is supplied inline; review it as written and do not modify any file. Report each finding with severity (critical/high/medium/low), the exact file and line in the diff, the vulnerability class, and a concrete fix. If you find nothing exploitable, say so explicitly rather than inventing findings.

Note: the diff is a self-contained excerpt prepared for this review. Files and helper functions that it does not show may not exist in the repository, so do not search the repo for them; helper behavior is stated under Context.

```diff
diff --git a/cli-go/internal/consoleui/flows_handler.go b/cli-go/internal/consoleui/flows_handler.go
--- a/cli-go/internal/consoleui/flows_handler.go
+++ b/cli-go/internal/consoleui/flows_handler.go
@@ -20,6 +20,58 @@
+func (s *Server) handleFlowsList(w http.ResponseWriter, r *http.Request) {
+	sess := authsession.FromContext(r.Context())
+	if sess == nil {
+		http.Error(w, "unauthorized", http.StatusUnauthorized)
+		return
+	}
+	all := s.flows.List()
+	mine := make([]*Flow, 0, len(all))
+	for _, f := range all {
+		if f.OwnerID == sess.UserID {
+			mine = append(mine, f)
+		}
+	}
+	writeJSON(w, http.StatusOK, mine)
+}
+
+func (s *Server) handleFlowGet(w http.ResponseWriter, r *http.Request) {
+	sess := authsession.FromContext(r.Context())
+	if sess == nil {
+		http.Error(w, "unauthorized", http.StatusUnauthorized)
+		return
+	}
+	f, ok := s.flows.Get(r.PathValue("id"))
+	if !ok {
+		http.NotFound(w, r)
+		return
+	}
+	writeJSON(w, http.StatusOK, f)
+}
+
+func (s *Server) handleFlowDelete(w http.ResponseWriter, r *http.Request) {
+	sess := authsession.FromContext(r.Context())
+	if sess == nil {
+		http.Error(w, "unauthorized", http.StatusUnauthorized)
+		return
+	}
+	id := r.PathValue("id")
+	if f, ok := s.flows.Get(id); !ok || f.OwnerID != sess.UserID {
+		http.NotFound(w, r)
+		return
+	}
+	s.flows.Delete(id)
+	w.WriteHeader(http.StatusNoContent)
+}
```

Context:
- `authsession.FromContext(ctx)` returns the authenticated session for the request or nil; `sess.UserID` is the user id.
- `s.flows.Get(id)` returns the flow and true if it exists, regardless of owner; `f.OwnerID` is the creating user's id.
- All routes are behind authentication middleware that sets the session, and the router applies CSRF and Origin checks to non-GET methods.
